/* One daily exercise card joins planned work with actual dated performance. */
const exerciseKey=s=>String(s||'').split('—')[0].normalize('NFKC').toLowerCase().replace(/[^\p{L}\p{N}]/gu,'');
function fullWeeklyProgram(){const days=[
[['Bench Press','صدر','6–10','Chest Press Machine'],['Incline Dumbbell Press','صدر','8–12','Incline Smith Press'],['Cable Fly','صدر','12–15','Pec Deck'],['Triceps Pushdown','تراي','10–15','Cable Overhead Extension'],['Dead Bug','بطن','10–12 / جهة','Bird Dog']],
[['Lat Pulldown','ظهر','8–12','Assisted Pull-up'],['Seated Cable Row','ظهر','8–12','Chest-supported Row'],['One-arm Dumbbell Row','ظهر','10–12 / جهة','One-arm Cable Row'],['Straight-arm Pulldown','ظهر','12–15','Cable Pullover'],['Dumbbell Curl','باي','10–12','EZ-bar Curl']],
[['Shoulder Press','كتف','8–12','Dumbbell Shoulder Press'],['Lateral Raise','كتف','12–15','Cable Lateral Raise'],['Reverse Pec Deck','كتف','12–15','Face Pull'],['Dumbbell Shrug','كتف','10–15','Cable Shrug'],['Dead Bug','بطن','10–12 / جهة','Bird Dog'],['Cable Crunch','بطن','12–15','Dead Bug']],
[['EZ-bar Curl','باي','8–12','Cable Curl'],['Hammer Curl','باي','10–12','Rope Curl'],['Triceps Pushdown','تراي','10–15','Band Pushdown'],['Overhead Cable Extension','تراي','10–15','Dumbbell Triceps Extension'],['Chest Press','صدر','10–12','Incline Push-up'],['Chest-supported Row','ظهر','10–12','Seated Cable Row']],
[['Leg Press','رجل','8–12','Goblet Squat'],['Dumbbell Romanian Deadlift','رجل','8–12','Cable Pull-through'],['Leg Curl','رجل','10–15','Sliding Leg Curl'],['Leg Extension','رجل','12–15','Step Up'],['Hip Thrust','رجل','10–12','Glute Bridge'],['Calf Raise','رجل','12–20','Seated Calf Raise']]];return days.flatMap((rows,d)=>rows.map(([exercise,group,reps,alternative],i)=>({id:`complete-v2-${d}-${i}`,session:String(d+1),exercise,group,reps,alternative,sets:3,weight:'',notes:(['رجل','صدر','ظهر'].includes(group)&&i<2?'راحة 90–120 ثانية. ':'راحة 60–90 ثانية. ')+(d===2&&group==='رجل'?'حمل خفيف كجلسة مساندة؛ اليوم الرئيسي للرجل الخميس. ':'')+'اترك 2–3 عدات ممكنة، وارفع الوزن تدريجيًا عند إتقان الحد الأعلى للعدات.'})));}
function upgradeTraining(){if(!window.fitnessAccount?.owner||activeProfile!=='default'||data.training.completeProgramVersion===2)return;const next=structuredClone(data),old=next.training.exercises||[],plan=fullWeeklyProgram();next.training.previousProgramV2=structuredClone(old);const move={رجل:'5',كتف:'3',باي:'4',تراي:'4',سواعد:'4'};for(const x of old){if(/^(weekly-v1-|pdf-|coach-)/.test(x.id))continue;const entry={...x,session:move[x.group]||x.session};const existing=plan.find(p=>p.session===entry.session&&exerciseKey(p.exercise)===exerciseKey(entry.exercise));if(existing)Object.assign(existing,entry);else plan.push(entry)}next.training.exercises=plan;next.training.completeProgramVersion=2;next.training.weeklySplitActive=true;next.training.programEffectiveDate=today();next.targets.workoutDays=5;validate(next);commit(next,'تم تحديث البرنامج: الرجل الخميس، والتمارين والأداء في مكان واحد')}
function matchingPlan(state,w){return (state.training.exercises||[]).find(p=>p.id===w.planId&&p.session===sessionForDate(w.date))||(state.training.exercises||[]).find(p=>p.session===sessionForDate(w.date)&&exerciseKey(p.exercise)===exerciseKey(w.exercise))}
function synchronizeWorkoutPlans(before,next){const changed=next.workouts.filter(w=>{const old=before.workouts.find(x=>x.id===w.id);return !old||JSON.stringify(old)!==JSON.stringify(w)});for(const w of changed){let p=matchingPlan(next,w);if(!p){p={id:uid(),session:sessionForDate(w.date),exercise:w.exercise,group:w.group,sets:Math.min(4,Math.max(1,w.sets.length)),reps:w.exerciseType==='كارديو'?'حسب المدة المسجلة':w.sets.map(s=>s.r).join(' / '),weight:'',alternative:'',notes:'أضيف من تمرين مسجل في '+w.date,exerciseType:w.exerciseType||'مقاومة'};next.training.exercises=[...(next.training.exercises||[]),p]}w.planId=p.id;next.training[w.date+':'+p.id]=true}
for(const old of before.workouts){const updated=next.workouts.find(w=>w.id===old.id);if(updated&&updated.date===old.date&&updated.planId===old.planId&&exerciseKey(updated.exercise)===exerciseKey(old.exercise))continue;const p=(before.training.previousProgramV2||[]).find(p=>p.id===old.planId)||matchingPlan(before,old);if(p&&!next.workouts.some(w=>w.date===old.date&&(w.planId===p.id||exerciseKey(w.exercise)===exerciseKey(p.exercise))))delete next.training[old.date+':'+p.id]}}
function dayExerciseRows(state,date){const historical=state.training.programEffectiveDate&&date<state.training.programEffectiveDate,base=historical&&state.training.previousProgramV2?state.training.previousProgramV2:(state.training.exercises||[]),rows=base.filter(p=>p.session===sessionForDate(date)).map(p=>({...p,actual:[]}));for(const w of state.workouts.filter(w=>w.date===date)){let row=rows.find(p=>p.id===w.planId)||rows.find(p=>exerciseKey(p.exercise)===exerciseKey(w.exercise));if(!row){row={id:'actual-'+w.id,exercise:w.exercise,group:w.group,sets:w.sets.length,reps:'',session:sessionForDate(date),actual:[],virtual:true};rows.push(row)}row.actual.push(w)}return rows}
const commitBeforeUnified=commit;commit=function(next,message){try{synchronizeWorkoutPlans(data,next);validate(next)}catch(e){notify(e.message,true);return false}return commitBeforeUnified(next,message)};
renderWorkouts=function(){trainingSession=sessionForDate(selected);const rows=dayExerciseRows(data,selected),done=rows.filter(r=>r.actual.length||data.training[selected+':'+r.id]).length;const labels={'1':'صدر وترايسبس وبطن','2':'ظهر وبايسبس','3':'أكتاف وبطن','4':'ذراعان + جزء علوي','5':'الرجل — الجلسة الرئيسية','6':'راحة','7':'كارديو اختياري'};const historical=data.training.programEffectiveDate&&selected<data.training.programEffectiveDate;return `<section class="card"><div class="card-head"><div><h2>تمارين يومك</h2><p class="sub">${pretty(selected)} · ${historical?'سجل وخطة سابقة':data.training.completeProgramVersion===2?labels[trainingSession]:esc(weeklyDayDetail(trainingSession))}</p></div><div class="quick-buttons">${button('+ تسجيل تمرين','workout')}<button class="button secondary" data-program="add">+ تمرين مخطط</button></div></div><div class="training-week">${trainingDays.map(([s,name])=>`<button class="button ${s===trainingSession?'':'secondary'}" data-program="session" data-id="${s}" ${s===trainingSession?'aria-current="date"':''}><strong>${name}</strong><small>${pretty(trainingDate(s),{day:'numeric',month:'short'})}</small><span>${esc(data.training.completeProgramVersion===2?labels[s]:weeklyDayDetail(s))}</span></button>`).join('')}</div><div class="quick-buttons">${planButton('الأسبوع السابق','previous-week')}${planButton('الأسبوع التالي','next-week')}</div><p class="notice">حفظ أداء أي تمرين يضيفه تلقائيًا إلى الخطة ويحدد «تم الهدف» في تاريخه الفعلي. إضافة تمرين مخطط دون أداء تتركه غير منجز.</p>${trainingSession==='6'&&data.training.weeklySplitActive?'<p class="notice">الجمعة راحة. أي نشاط تختار تسجيله يظهر هنا.</p>':''}${trainingSession==='7'&&data.training.weeklySplitActive?`<p class="notice">كلاس كارديو اختياري؛ ليس ضمن هدف أيام المقاومة الخمسة.</p>${planButton('تسجيل كلاس كارديو','cardio')}`:''}<h3>${done} / ${rows.length} تم الهدف</h3>${progress(done,rows.length)}${rows.map(p=>`<article class="record"><div class="record-head"><div><h3>${esc(p.exercise)}</h3><p class="sub">${esc(p.group)}${p.reps?' · '+p.sets+' جولات × '+esc(p.reps):''}</p></div>${p.actual.length?'<span class="chip">✓ تم الهدف · الأداء مسجل</span>':`<label class="check-label"><input type="checkbox" data-program-done="${esc(p.id)}" ${data.training[selected+':'+p.id]?'checked':''}> تم الهدف</label>`}</div>${typeof exerciseMedia==='function'?exerciseMedia(p.exercise):''}${p.alternative?`<p class="sub">البديل: ${esc(p.alternative)}</p>`:''}${p.notes?`<p class="sub">${esc(p.notes)}</p>`:''}${p.actual.map(w=>`<div class="actual-performance"><div class="chips">${w.exerciseType==='كارديو'?`<span class="chip">${fmt(w.duration)} دقيقة</span>`:w.sets.map((s,i)=>`<span class="chip">الجولة ${i+1} · <bdi>${fmt(s.w)} kg × ${s.r}</bdi></span>`).join('')}</div>${recordActions('workouts',w.id)}</div>`).join('')}<div class="quick-buttons">${!p.actual.length?planButton('تسجيل الأداء','log',`data-id="${esc(p.id)}"`):''}${!p.virtual&&!historical?planButton('تعديل الخطة','edit',`data-id="${esc(p.id)}"`):''}${!p.actual.length&&!p.virtual&&!historical?planButton('حذف من الخطة','delete',`data-id="${esc(p.id)}"`):''}</div></article>`).join('')||'<p class="empty">لا يوجد تمرين مخطط لهذا اليوم. يمكنك إضافة تمرين من الأعلى.</p>'}</section><section class="card"><h2>طريقة تنفيذ البرنامج</h2><p>٥–٦ تمارين في اليوم، ٣ جولات لكل تمرين، والجولة الرابعة اختيارية. استهدف نحو ٥٠–٦٠ دقيقة؛ عند ضيق الوقت اختصر آخر تمرين مساعد.</p><p>ابدأ بإحماء ٥–٨ دقائق وجولات خفيفة للحركة الأولى. راحة ٩٠–١٢٠ ثانية للحركات المركبة و٦٠–٩٠ ثانية للعزل. لا تُحسب جولات الإحماء ضمن جولات العمل.</p><p>اختر وزنًا يترك ٢–٣ عدات ممكنة. عندما تبلغ أعلى العدات بجميع الجولات بحركة سليمة في جلستين، زد الوزن بأصغر زيادة متاحة. خفّض الحمل عند التعب، وأوقف الحركة التي تسبب ألمًا.</p><p class="sub">الأوزان تُختار من أدائك الحالي. راجع الخطة عند وجود إصابة أو حالة صحية تؤثر على التدريب.</p><a class="text-button" href="https://www.acsm.org/wp-content/uploads/2026/03/Resistance-Training-Position-Stand-infographic.pdf" target="_blank" rel="noopener">مرجع مبادئ تدريب المقاومة — ACSM</a><div class="timer-box"><strong class="timer" id="timer">${timerText()}</strong><div class="actions">${button('60 ثانية','timer60',true)}${button('90 ثانية','timer90',true)}<button class="text-button" data-action="timerStop">إيقاف</button></div></div></section>`};
